//! Oracle table generated by `target/canon/winemapi/gen.py`. Do not edit.
//!
//! Each row is one run of Wine commit 9f8c4ae4d35c7ff4153267aba9618c026f5f5583 (`dlls/winemapi/main.c` and
//! `sendmail.c`), compiled verbatim with `gcc -fsanitize=address,undefined -g`
//! and run in its own process. The sanitizers reported nothing for the 24 rows, so no vector is excluded.
//!
//! `mailto` is present only where the C reached its `winebrowser` fallback.
//! File rows carry the unix path the caller resolves: `None` where the C
//! `wine_get_unix_file_name` returns NULL. The subject and body of the `mailto`
//! rows contain only characters that `UrlEscapeA` leaves unchanged, so those
//! rows do not exercise the escaping itself.

use super::*;

struct LogonRow {
    id: &'static str,
    session: bool,
    ret: u32,
    handle: Option<u32>,
}

struct LogoffRow {
    id: &'static str,
    ret: u32,
}

struct ResolveRow {
    id: &'static str,
    name: Option<&'static [u8]>,
    expected: Result<(u32, &'static [u8], &'static [u8]), u32>,
}

struct IsNonEmptyRow {
    id: &'static str,
    text: Option<&'static [u8]>,
    expected: bool,
}

struct TargetRow {
    id: &'static str,
    class: u32,
    address: &'static [u8],
    argv: &'static [&'static [u8]],
}

struct SendRow {
    id: &'static str,
    message: Option<Message<'static>>,
    argv: Result<&'static [&'static [u8]], u32>,
    mailto: Option<&'static [u8]>,
}

