#[test]
fn logon_matches_oracle() {
    for row in LOGON_ROWS {
        let mut handle = 0;
        let ret = logon(row.session.then_some(&mut handle));
        assert_eq!(ret, row.ret, "{}", row.id);
        assert_eq!(row.session.then_some(handle), row.handle, "{}", row.id);
    }
}

#[test]
fn logoff_matches_oracle() {
    for row in LOGOFF_ROWS {
        assert_eq!(logoff(), row.ret, "{}", row.id);
    }
}

#[test]
fn resolve_name_matches_oracle() {
    for row in RESOLVE_ROWS {
        let got = resolve_name(row.name).map(|recip| (recip.class, recip.address, recip.name));
        let want = row
            .expected
            .map(|(class, address, name)| (class, address.to_vec(), name.to_vec()));
        assert_eq!(got, want, "{}", row.id);
    }
}

#[test]
fn is_non_empty_matches_oracle() {
    for row in IS_NON_EMPTY_ROWS {
        assert_eq!(is_non_empty(row.text), row.expected, "{}", row.id);
    }
}

#[test]
fn add_target_matches_oracle() {
    for row in TARGET_ROWS {
        let mut argv = Vec::new();
        add_target(&mut argv, row.class, row.address);
        assert_eq!(argv, row.argv, "{}", row.id);
    }
}

#[test]
fn send_mail_matches_oracle() {
    for row in SEND_ROWS {
        let argv = send_mail_argv(row.message.as_ref()).map(|argv| argv.to_vec());
        assert_eq!(argv, row.argv.map(<[&[u8]]>::to_vec), "{}", row.id);
        if let (Some(message), Some(expected)) = (&row.message, row.mailto) {
            let subject = message.subject.unwrap_or(b"");
            let body = message.note_text.unwrap_or(b"");
            assert_eq!(mailto_url(message, subject, body), expected, "{}", row.id);
        }
    }
}
